namespace epycbench::runtime::ipc{namespace{
auto err(std::string code,std::string classification)->core::Error{return{.category=core::ErrorCategory::runtime,.code=core::StableErrorCode{std::move(code)},.message="Controller-runner IPC failure",.operation="runtime_ipc",.os_error=std::nullopt,.context=nlohmann::json{{"classification",std::move(classification)}},.severity=core::ErrorSeverity::error,.continuation=core::ContinuationPolicy::abort_command};}
auto caught(bool unknown=false)->core::Error{return err(unknown?"runtime.ipc.contained_unknown_failure":"runtime.ipc.contained_exception","public_boundary");}
auto decimal(std::string_view s,bool positive)->std::expected<std::uint64_t,core::Error>{if(s.empty()||(s.size()>1&&s[0]=='0'))return std::unexpected{err("runtime.ipc.invalid_argument","noncanonical_decimal")};std::uint64_t v{};auto [p,e]=std::from_chars(s.data(),s.data()+s.size(),v);if(e!=std::errc{}||p!=s.data()+s.size()||(positive&&v==0))return std::unexpected{err("runtime.ipc.invalid_argument",positive&&v==0?"zero_request_id":"invalid_decimal")};return v;}
constexpr std::array tokens{std::pair{MessageType::placement_request,std::string_view{"placement_request"}},std::pair{MessageType::cancel_request,std::string_view{"cancel_request"}},std::pair{MessageType::request_accepted,std::string_view{"request_accepted"}},std::pair{MessageType::placement_succeeded,std::string_view{"placement_succeeded"}},std::pair{MessageType::request_cancelled,std::string_view{"request_cancelled"}},std::pair{MessageType::request_failed,std::string_view{"request_failed"}}};
constexpr std::array profiles{std::pair{MessageType::placement_request,std::string_view{"epycbench.placement-request/v2"}},std::pair{MessageType::cancel_request,std::string_view{"epycbench.cancel-request/v1"}},std::pair{MessageType::request_accepted,std::string_view{"epycbench.request-accepted/v1"}},std::pair{MessageType::placement_succeeded,std::string_view{"epycbench.placement-proof/v1"}},std::pair{MessageType::request_cancelled,std::string_view{"epycbench.runner-cancelled/v1"}},std::pair{MessageType::request_failed,std::string_view{"epycbench.runner-failure/v1"}}};
auto floats(const nlohmann::json&j)->bool{if(j.is_number_float())return true;if(j.is_structured())for(const auto&v:j)if(floats(v))return true;return false;}
auto exact(const nlohmann::json&j,std::initializer_list<std::string_view>n)->bool{if(!j.is_object()||j.size()!=n.size())return false;for(auto x:n)if(!j.contains(x))return false;return true;}
auto interrupted(const core::Error&e)->bool{return e.code.value()=="runtime.ipc.io_failure"&&e.context.is_object()&&e.context.value("classification","")=="interrupted";}
auto stable_token(std::string_view s,std::size_t max)->bool{if(s.empty()||s.size()>max||s[0]<'a'||s[0]>'z')return false;return std::ranges::all_of(s.substr(1),[](char c){return(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='_'||c=='.'||c=='-';});}
auto context_ok(std::string_view k,std::string_view v)->bool{static const std::map<std::string_view,std::set<std::string_view>>m{{"channel",{"control","event"}},{"protocol_phase",{"framing","encoding","decoding","state_validation"}},{"runner_phase",{"startup","placement","cleanup"}},{"component",{"ipc","affinity","mapping","numa_bind","initialization","page_query","threshold","read_only","worker","service","runner"}},{"expected_message",{"placement_request","cancel_request","request_accepted","placement_succeeded","request_cancelled","request_failed","stream_end"}},{"received_message",{"placement_request","cancel_request","request_accepted","placement_succeeded","request_cancelled","request_failed","stream_end","unknown"}},{"frame_size_category",{"zero","within_limit","over_limit"}},{"sequence_category",{"gap","duplicate","reversal","unexpected"}},{"verification_phase",{"before","after"}}};if(k=="underlying_code")return stable_token(v,128);auto i=m.find(k);return i!=m.end()&&i->second.contains(v);}
auto parse_failure(const nlohmann::json&j)->std::expected<RemoteFailure,core::Error>{
 if(!j.is_object()){return std::unexpected{err("runtime.ipc.unsafe_failure_payload","nonobject")};}
 static const std::set<std::string>req{"category","code","operation","severity","continuation","context"},opt{"classification","os_error"};
 for(auto&x:req){if(!j.contains(x))return std::unexpected{err("runtime.ipc.unsafe_failure_payload","missing_member")};}
 for(auto&[k,v]:j.items()){(void)v;if(!req.contains(k)&&!opt.contains(k))return std::unexpected{err("runtime.ipc.unsafe_failure_payload","unknown_member")};}
 if(!j["category"].is_string()||!j["code"].is_string()||!j["operation"].is_string()||!j["severity"].is_string()||!j["continuation"].is_string()||!j["context"].is_object()||!stable_token(j["code"].get_ref<const std::string&>(),128)||!stable_token(j["operation"].get_ref<const std::string&>(),64))return std::unexpected{err("runtime.ipc.unsafe_failure_payload","invalid_member")};
 std::optional<std::string>cl;if(j.contains("classification")){if(!j["classification"].is_string()||!stable_token(j["classification"].get_ref<const std::string&>(),64))return std::unexpected{err("runtime.ipc.unsafe_failure_payload","invalid_classification")};cl=j["classification"].get<std::string>();}
 std::optional<int>os;if(j.contains("os_error")){if(!j["os_error"].is_number_integer()){return std::unexpected{err("runtime.ipc.unsafe_failure_payload","invalid_os_error")};}auto v=j["os_error"].get<long long>();if(v<=0||v>std::numeric_limits<int>::max())return std::unexpected{err("runtime.ipc.unsafe_failure_payload","invalid_os_error")};os=static_cast<int>(v);}
 for(auto&[k,v]:j["context"].items())if(!v.is_string()||!context_ok(k,v.get_ref<const std::string&>()))return std::unexpected{err("runtime.ipc.unsafe_failure_payload","unsafe_context")};
 try{return RemoteFailure{j["category"].get<core::ErrorCategory>(),core::StableErrorCode{j["code"].get<std::string>()},j["operation"].get<std::string>(),cl,os,j["severity"].get<core::ErrorSeverity>(),j["continuation"].get<core::ContinuationPolicy>(),j["context"].get<nlohmann::ordered_json>()};}catch(...){return std::unexpected{err("runtime.ipc.unsafe_failure_payload","invalid_enum")};}}
} // namespace

auto message_type_token(MessageType t)noexcept->std::string_view{for(auto[x,s]:tokens)if(x==t)return s;return{};}auto message_payload_profile(MessageType t)noexcept->std::string_view{for(auto[x,s]:profiles)if(x==t)return s;return{};}auto parse_message_type(std::string_view s)->std::expected<MessageType,core::Error>{for(auto[x,v]:tokens)if(v==s)return x;return std::unexpected{err("runtime.ipc.unknown_message","unknown_type")};}
auto RequestId::create(std::uint64_t v)->std::expected<RequestId,core::Error>{if(!v)return std::unexpected{err("runtime.ipc.invalid_argument","zero_request_id")};return RequestId{v};}auto RequestId::parse(std::string_view s)->std::expected<RequestId,core::Error>{auto v=decimal(s,true);if(!v)return std::unexpected{v.error()};return RequestId{*v};}auto RequestId::text()const->std::string{return std::to_string(value_);}auto SequenceNumber::parse(std::string_view s)->std::expected<SequenceNumber,core::Error>{auto v=decimal(s,false);if(!v)return std::unexpected{v.error()};return SequenceNumber{*v};}auto SequenceNumber::text()const->std::string{return std::to_string(value_);}
auto Envelope::create(MessageType t,RequestId r,SequenceNumber s,nlohmann::ordered_json p)->std::expected<Envelope,core::Error>{return create(t,r,s,std::move(p),message_payload_profile(t));}
auto Envelope::create(MessageType t,RequestId r,SequenceNumber s,nlohmann::ordered_json p,std::string_view profile)->std::expected<Envelope,core::Error>{try{if(!p.is_object()||floats(p))return std::unexpected{err("runtime.ipc.invalid_payload",p.is_object()?"floating_point":"nonobject")};const bool additive=(t==MessageType::placement_request&&(profile=="epycbench.placement-request/v3"||profile=="epycbench.placement-request/v4"))||(t==MessageType::placement_succeeded&&profile=="epycbench.placement-proof/v2");if(profile!=message_payload_profile(t)&&!additive)return std::unexpected{err("runtime.ipc.invalid_payload","profile_mismatch")};return Envelope{t,r,s,std::move(p),std::string{profile}};}catch(const std::exception&){return std::unexpected{caught()};}catch(...){return std::unexpected{caught(true)};}}
auto encode_body(const Envelope&e)->std::expected<std::string,core::Error>{try{nlohmann::json j{{"protocol",protocol_profile},{"type",message_type_token(e.type())},{"request_id",e.request_id().text()},{"sequence",e.sequence().text()},{"payload_profile",e.payload_profile()},{"payload",e.payload()}};auto c=core::canonicalize_json(j);if(!c)return std::unexpected{err("runtime.ipc.invalid_encoding","canonicalization")};return c;}catch(const std::exception&){return std::unexpected{caught()};}catch(...){return std::unexpected{caught(true)};}}
auto decode_body(std::string_view b)->std::expected<Envelope,core::Error>{try{if(b.starts_with("\xef\xbb\xbf")||b.find('\0')!=std::string_view::npos)return std::unexpected{err("runtime.ipc.invalid_encoding","bom_or_nul")};bool dup=false;std::vector<std::set<std::string>>keys;auto cb=[&](int,nlohmann::json::parse_event_t ev,nlohmann::json&v){if(ev==nlohmann::json::parse_event_t::object_start)keys.emplace_back();else if(ev==nlohmann::json::parse_event_t::key&&!keys.back().insert(v.get<std::string>()).second)dup=true;else if(ev==nlohmann::json::parse_event_t::object_end)keys.pop_back();return true;};auto j=nlohmann::json::parse(b,cb,false);if(j.is_discarded())return std::unexpected{err("runtime.ipc.invalid_encoding","invalid_json_or_utf8")};if(dup)return std::unexpected{err("runtime.ipc.invalid_encoding","duplicate_key")};if(floats(j))return std::unexpected{err("runtime.ipc.invalid_encoding","floating_point")};if(!exact(j,{"protocol","type","request_id","sequence","payload_profile","payload"}))return std::unexpected{err("runtime.ipc.invalid_envelope","member_set")};if(!j["protocol"].is_string()||j["protocol"]!=protocol_profile)return std::unexpected{err("runtime.ipc.unsupported_protocol","protocol")};if(!j["type"].is_string()||!j["request_id"].is_string()||!j["sequence"].is_string()||!j["payload_profile"].is_string()||!j["payload"].is_object())return std::unexpected{err("runtime.ipc.invalid_envelope","member_type")};auto t=parse_message_type(j["type"].get_ref<const std::string&>());if(!t)return std::unexpected{t.error()};const auto profile=j["payload_profile"].get_ref<const std::string&>();const bool additive=(*t==MessageType::placement_request&&(profile=="epycbench.placement-request/v3"||profile=="epycbench.placement-request/v4"))||(*t==MessageType::placement_succeeded&&profile=="epycbench.placement-proof/v2");if(profile!=message_payload_profile(*t)&&!additive)return std::unexpected{err("runtime.ipc.invalid_payload","profile_mismatch")};auto r=RequestId::parse(j["request_id"].get_ref<const std::string&>());auto s=SequenceNumber::parse(j["sequence"].get_ref<const std::string&>());if(!r)return std::unexpected{r.error()};if(!s)return std::unexpected{s.error()};auto c=core::canonicalize_json(j);if(!c)return std::unexpected{err("runtime.ipc.invalid_encoding","canonicalization")};if(*c!=b)return std::unexpected{err("runtime.ipc.noncanonical_json","byte_mismatch")};return Envelope::create(*t,*r,*s,j["payload"].get<nlohmann::ordered_json>(),profile);}catch(const std::exception&){return std::unexpected{caught()};}catch(...){return std::unexpected{caught(true)};}}
auto encode_frame(const Envelope&e)->std::expected<std::vector<std::byte>,core::Error>{auto b=encode_body(e);if(!b)return std::unexpected{b.error()};if(b->empty()||b->size()>maximum_frame_body_size)return std::unexpected{err("runtime.ipc.frame_too_large",b->empty()?"zero":"over_limit")};auto n=static_cast<std::uint32_t>(b->size());std::vector<std::byte>v(4+b->size());for(int i=0;i<4;++i)v[static_cast<std::size_t>(i)]=std::byte{static_cast<unsigned char>(n>>(24-8*i))};std::transform(b->begin(),b->end(),v.begin()+4,[](char c){return std::byte{static_cast<unsigned char>(c)};});return v;}
auto read_frame(ByteReader&r)->std::expected<FrameReadResult,core::Error>{try{std::array<std::byte,4>h{};auto fill=[&](std::span<std::byte>s,bool clean)->std::expected<bool,core::Error>{std::size_t q=0;while(q<s.size()){auto n=r.read(s.subspan(q));if(!n){if(interrupted(n.error()))continue;return std::unexpected{n.error()};}if(*n>s.size()-q)return std::unexpected{err("runtime.ipc.io_failure","invalid_progress")};if(!*n){if(clean&&q==0)return false;return std::unexpected{err("runtime.ipc.truncated_frame",clean?"header":"body")};}q+=*n;}return true;};auto a=fill(h,true);if(!a)return std::unexpected{a.error()};if(!*a)return FrameReadResult{EndOfStream{}};auto n=(std::to_integer<std::uint32_t>(h[0])<<24)|(std::to_integer<std::uint32_t>(h[1])<<16)|(std::to_integer<std::uint32_t>(h[2])<<8)|std::to_integer<std::uint32_t>(h[3]);if(!n||n>maximum_frame_body_size)return std::unexpected{err("runtime.ipc.frame_too_large",!n?"zero":"over_limit")};std::vector<std::byte>v(n);auto a2=fill(v,false);if(!a2)return std::unexpected{a2.error()};std::string b(n,'\0');std::transform(v.begin(),v.end(),b.begin(),[](std::byte x){return static_cast<char>(std::to_integer<unsigned char>(x));});auto e=decode_body(b);if(!e)return std::unexpected{e.error()};return FrameReadResult{std::move(*e)};}catch(const std::exception&){return std::unexpected{caught()};}catch(...){return std::unexpected{caught(true)};}}
auto write_frame(ByteWriter&w,const Envelope&e)->std::expected<void,core::Error>{try{auto f=encode_frame(e);if(!f)return std::unexpected{f.error()};std::size_t p=0;while(p<f->size()){auto n=w.write(std::span<const std::byte>{*f}.subspan(p));if(!n){if(interrupted(n.error()))continue;return std::unexpected{n.error()};}if(*n>f->size()-p)return std::unexpected{err("runtime.ipc.io_failure","invalid_progress")};if(!*n)return std::unexpected{err("runtime.ipc.io_failure","zero_progress")};p+=*n;}return{};}catch(const std::exception&){return std::unexpected{caught()};}catch(...){return std::unexpected{caught(true)};}}
auto RunnerControlState::accept(const Envelope&e)->std::expected<void,core::Error>{if(e.type()!=MessageType::placement_request&&e.type()!=MessageType::cancel_request)return std::unexpected{err("runtime.ipc.unexpected_message","wrong_direction")};auto seq=phase_==Phase::start?0U:1U;if(e.sequence().value()!=seq)return std::unexpected{err("runtime.ipc.sequence_mismatch","unexpected")};if(phase_==Phase::start){if(e.type()!=MessageType::placement_request)return std::unexpected{err("runtime.ipc.unexpected_message","cancel_before_request")};request_=e.request_id().value();phase_=Phase::requested;return{};}if(e.request_id().value()!=request_)return std::unexpected{err("runtime.ipc.request_mismatch","active_request")};if(phase_==Phase::cancelled)return std::unexpected{err("runtime.ipc.unexpected_message","duplicate_cancel")};if(e.type()!=MessageType::cancel_request)return std::unexpected{err("runtime.ipc.unexpected_message","second_request")};phase_=Phase::cancelled;return{};}auto RunnerControlState::end(bool terminal)->std::expected<void,core::Error>{if(phase_==Phase::start||!terminal)return std::unexpected{err("runtime.ipc.unexpected_eof","control")};return{};}
auto ControllerEventState::accept(const Envelope&e)->std::expected<void,core::Error>{if(e.request_id()!=request_)return std::unexpected{err("runtime.ipc.request_mismatch","active_request")};auto seq=phase_==Phase::start?0U:1U;if(e.sequence().value()!=seq)return std::unexpected{err("runtime.ipc.sequence_mismatch","unexpected")};if(phase_==Phase::start){if(e.type()!=MessageType::request_accepted)return std::unexpected{err("runtime.ipc.unexpected_message","terminal_before_acceptance")};phase_=Phase::accepted;return{};}if(phase_==Phase::terminal)return std::unexpected{err("runtime.ipc.unexpected_message","after_terminal")};if(e.type()!=MessageType::placement_succeeded&&e.type()!=MessageType::request_cancelled&&e.type()!=MessageType::request_failed)return std::unexpected{err("runtime.ipc.unexpected_message","nonterminal")};phase_=Phase::terminal;return{};}auto ControllerEventState::end()->std::expected<void,core::Error>{if(phase_!=Phase::terminal)return std::unexpected{err("runtime.ipc.unexpected_eof","event")};return{};}
auto project_failure(const core::Error&e)->std::expected<nlohmann::ordered_json,core::Error>{try{nlohmann::json j{{"category",e.category},{"code",e.code.value()},{"operation",e.operation},{"severity",e.severity},{"continuation",e.continuation},{"context",nlohmann::json::object()}};if(e.os_error){if(e.os_error->value<=0)return std::unexpected{err("runtime.ipc.unsafe_failure_payload","invalid_os_error")};j["os_error"]=e.os_error->value;}if(!e.context.is_object())return std::unexpected{err("runtime.ipc.unsafe_failure_payload","context_type")};for(auto&[k,v]:e.context.items()){if(k=="classification"){if(!v.is_string()||!stable_token(v.get_ref<const std::string&>(),64))return std::unexpected{err("runtime.ipc.unsafe_failure_payload","invalid_classification")};j["classification"]=v;}else{if(!v.is_string()||!context_ok(k,v.get_ref<const std::string&>()))return std::unexpected{err("runtime.ipc.unsafe_failure_payload","unsafe_context")};j["context"][k]=v;}}auto x=parse_failure(j);if(!x)return std::unexpected{x.error()};return j.get<nlohmann::ordered_json>();}catch(const std::exception&){return std::unexpected{caught()};}catch(...){return std::unexpected{caught(true)};}}auto parse_remote_failure(const nlohmann::json&j)->std::expected<RemoteFailure,core::Error>{try{return parse_failure(j);}catch(const std::exception&){return std::unexpected{caught()};}catch(...){return std::unexpected{caught(true)};}}
} // namespace epycbench::runtime::ipc
